// Split the incoming conversation into: the latest user turn (agent input)
// and the prior turns (chat history the AI Agent node replays for context).
const body = $json.body || $json;
const messages = Array.isArray(body.messages) ? body.messages : [];
const leadId = body.leadId || null;
const calendlyUrl = body.calendlyUrl || $env.CALENDLY_URL || '';

const lastUser = [...messages].reverse().find(m => m.role === 'user');
const history = messages.filter(m => m !== lastUser);
const turnCount = messages.filter(m => m.role === 'user').length;

// Flatten prior turns into a text block the agent can read as context.
const historyText = history
  .map(m => `${m.role === 'user' ? 'Parent' : 'Sarah'}: ${m.content}`)
  .join('\n');

return [{ json: {
  chatInput: lastUser ? lastUser.content : '',
  historyText,
  messages,
  leadId,
  calendlyUrl,
  turnCount
} }];

// Returns the Calendly link. The workflow surfaces it to the UI by parsing
// the agent's intermediate steps for this tool's observation.
return $env.CALENDLY_URL || '';

// Pull the agent reply, plus structured schools/calendar from intermediateSteps.
// The search_schools observation is Supabase PostgREST JSON (snake_case) — map it
// to the camelCase shape the chatbot UI (SchoolCard) expects.
const prep = $('Prep Input').item.json;
const agent = $json;
const reply = agent.output || agent.text || '';
const steps = agent.intermediateSteps || [];

function toCamel(row) {
  return {
    id: row.id,
    slug: row.slug,
    name: row.name,
    city: row.city,
    country: row.country,
    website: row.website,
    curricula: row.curricula,
    ageFrom: row.age_from,
    ageTo: row.age_to,
    feesMinUsd: row.fees_min_usd,
    feesMaxUsd: row.fees_max_usd,
    boarding: row.boarding,
    day: row.day,
    description: row.description,
    heroImageUrl: row.hero_image_url,
  };
}

function parseObs(obs) {
  if (obs == null) return null;
  if (typeof obs === 'object') return obs;
  try { return JSON.parse(obs); } catch { return obs; }
}

let schools = null;
let calendlyUrl = null;

for (const step of steps) {
  const action = step.action || step;
  const tool = action.tool || action.toolName;
  const obs = parseObs(step.observation);
  if (tool === 'search_schools' && Array.isArray(obs)) {
    // Curriculum partial-match (e.g. 'IB' -> 'IB (DP)') is done here because
    // PostgREST can't filter a jsonb array partial in a query param.
    const want = (action.toolInput && action.toolInput.curriculum) || null;
    let rows = obs;
    if (want && want !== 'Any') {
      const w = String(want).toLowerCase();
      rows = rows.filter(r => JSON.stringify(r.curricula || '').toLowerCase().includes(w));
    }
    schools = rows.slice(0, 4).map(toCamel);
  } else if (tool === 'offer_calendar') {
    calendlyUrl = (typeof obs === 'string' ? obs : (obs && obs.url)) || prep.calendlyUrl || '';
  }
}

return [{ json: {
  reply,
  schools,
  calendlyUrl,
  leadId: prep.leadId,
  messages: prep.messages
} }];

// Combine the agent reply/structured data with the scoring result, then
// classify (mirrors src/Chatbot/lib/scoring.ts: >=70 hot, >=40 warm, else cold).
const structured = $('Extract Structured').item.json;

let parsed = {};
try {
  const content = $json.choices && $json.choices[0] && $json.choices[0].message.content;
  parsed = JSON.parse(content || '{}');
} catch { parsed = {}; }

const timeline = parsed.timeline || 0;
const forcing_function = parsed.forcing_function || 0;
const commitment = parsed.commitment || 0;
const location = parsed.location || 0;
const budget = parsed.budget || 0;
const total = timeline + forcing_function + commitment + location + budget;
const classification = total >= 70 ? 'hot' : total >= 40 ? 'warm' : 'cold';

const breakdown = { timeline, forcing_function, commitment, location, budget, total };

return [{ json: {
  reply: structured.reply,
  schools: structured.schools,
  calendlyUrl: structured.calendlyUrl,
  leadId: structured.leadId,
  score: {
    total,
    classification,
    breakdown,
    location_text: parsed.location_text || null,
    timeline_text: parsed.timeline_text || null,
    forcing_function_text: parsed.forcing_function_text || null,
    curriculum_text: parsed.curriculum_text || null,
    child_age_text: parsed.child_age_text || null
  }
} }];
